package com.mockarena.assessment.domain;
import org.springframework.data.jpa.repository.JpaRepository;
import java.util.*;
public interface AssessmentVersionRepository extends JpaRepository<AssessmentVersion, UUID> { Optional<AssessmentVersion> findByAssessmentIdAndVersionNumber(UUID assessmentId, int versionNumber); Optional<AssessmentVersion> findTopByAssessmentIdOrderByVersionNumberDesc(UUID assessmentId); List<AssessmentVersion> findByAssessmentIdOrderByVersionNumberDesc(UUID assessmentId); @org.springframework.data.jpa.repository.Query(value = "select av.* from assessment.assessment_versions av join assessment.assessments a on a.id=av.assessment_id left join assessment.public_assessment_catalogue p on p.assessment_version_id=av.id where a.lifecycle_status='PUBLISHED' and a.visibility='PUBLIC' and a.current_published_version_id=av.id and av.status='PUBLISHED' and p.assessment_version_id is null", nativeQuery = true) List<AssessmentVersion> findCurrentPublicPublishedWithoutCatalogueProjection(); }
